using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer accepts expressions
        // like DateTime.UtcNow that are evaluated at migration time.
        // Use a fixed seed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }  }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfAppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The Cosmos provider now uses
        // "$type" instead of "Discriminator" as the default discriminator property.
        // For existing documents that already store "Discriminator", you must
        // explicitly configure the old property name to avoid data mismatches.
        modelBuilder.Entity<Product>(b =>
        {
            b.HasDiscriminatorInJsonProperty("Discriminator");
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Category { get; set; } = null!;
}

// --- Cosmos query service demonstrating sync-to-async migration ---

class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // EF Core 9 breaking change: Synchronous I/O is no longer supported
    // by the Cosmos DB provider. All queries must use async methods.
    // Before (would throw InvalidOperationException in EF Core 9):
    //   var products = _db.Products.Where(p => p.Category == category).ToList();
    // After:
    public async Task<List<Product>> GetProductsByCategoryAsync(string category)
    {
        return await _db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    // Before (sync First would throw):
    //   var product = _db.Products.First(p => p.Id == id);
    // After:
    public async Task<Product> GetProductByIdAsync(string id)
    {
        return await _db.Products
            .FirstAsync(p => p.Id == id);
    }
}

